/* Commit 25.15 -- "Fabrigray Cotización Comercial" Print Format.
   Print-safe CSS: table-based layout only (no CSS grid, no flexbox, no
   position:fixed, no vh/vw, no JS) -- wkhtmltopdf compatibility takes
   priority over matching the reference pixel-for-pixel (section 25/3).
   Every selector is scoped under .fg-pdf -- never a bare table/td/tr/
   svg/img/h1 selector that could leak into another print format sharing
   the same print/PDF stylesheet. */

.fg-pdf {
	font-family: "Helvetica Neue", Arial, sans-serif;
	color: #1c2b39;
	font-size: 9.5pt;
	line-height: 1.35;
}

.fg-pdf table {
	width: 100%;
	border-collapse: collapse;
}

/* ---------- Header ---------- */

.fg-pdf-header-table {
	margin-bottom: 10px;
}

.fg-pdf-header-logo-cell {
	width: 90px;
	vertical-align: middle;
}

.fg-pdf-logo img {
	max-width: 80px;
	max-height: 80px;
}

.fg-pdf-logo-placeholder {
	width: 74px;
	height: 74px;
	border-radius: 50%;
	background: #2f7fc2;
	color: #ffffff;
	font-weight: bold;
	font-size: 11pt;
	text-align: center;
	line-height: 1.15;
	padding-top: 20px;
}

.fg-pdf-header-brand-cell {
	vertical-align: middle;
	text-align: center;
	padding: 0 12px;
}

.fg-pdf-brand-name {
	color: #0d3b66;
	font-size: 22pt;
	font-weight: bold;
	letter-spacing: 0.5px;
}

.fg-pdf-brand-tagline {
	color: #2f7fc2;
	font-size: 8.5pt;
	font-style: italic;
	margin-top: 3px;
}

.fg-pdf-header-card-cell {
	width: 160px;
	vertical-align: top;
}

.fg-pdf-quote-card {
	background: #0d3b66;
	color: #ffffff;
	border-radius: 6px;
	padding: 8px 12px;
	text-align: center;
}

.fg-pdf-quote-card-label {
	font-size: 9pt;
	font-weight: bold;
	letter-spacing: 1px;
}

.fg-pdf-quote-card-number {
	font-size: 16pt;
	font-weight: bold;
	margin-top: 2px;
}

.fg-pdf-quote-card-date {
	font-size: 8pt;
	margin-top: 4px;
	opacity: 0.92;
}

/* ---------- Intro ---------- */

.fg-pdf-intro {
	text-align: center;
	color: #2f7fc2;
	font-style: italic;
	font-size: 8.5pt;
	margin-bottom: 10px;
}

/* ---------- Client info box ---------- */

.fg-pdf-client-table {
	background: #eaf4fb;
	border-radius: 6px;
	margin-bottom: 10px;
}

.fg-pdf-client-cell {
	padding: 7px 10px;
	vertical-align: top;
	width: 25%;
}

.fg-pdf-icon {
	width: 14px;
	height: 14px;
	color: #2f7fc2;
	vertical-align: top;
	margin-right: 5px;
}

.fg-pdf-client-text {
	display: inline;
}

.fg-pdf-client-label {
	display: block;
	font-size: 7pt;
	font-weight: bold;
	color: #5c7791;
	letter-spacing: 0.4px;
}

.fg-pdf-client-value {
	display: block;
	font-size: 8.5pt;
	font-weight: bold;
	color: #1c2b39;
}

/* ---------- Items table ---------- */

.fg-pdf-items {
	margin-bottom: 10px;
}

.fg-pdf-items thead {
	display: table-header-group;
}

.fg-pdf-items tbody tr {
	page-break-inside: avoid;
}

.fg-pdf-items th {
	background: #0d3b66;
	color: #ffffff;
	font-size: 7.5pt;
	font-weight: bold;
	padding: 6px 5px;
	text-align: center;
	letter-spacing: 0.3px;
}

.fg-pdf-items td {
	padding: 5px;
	border-bottom: 1px solid #e2e8ee;
	font-size: 8.5pt;
	text-align: center;
	vertical-align: middle;
}

.fg-pdf-items tbody tr:nth-child(even) td {
	background: #f5f9fc;
}

.fg-pdf-col-desc {
	text-align: left !important;
}

.fg-pdf-col-num {
	text-align: right !important;
}

.fg-pdf-item-code {
	font-size: 6.5pt;
	color: #8496a6;
	margin-top: 1px;
}

/* ---------- Bottom section: validity + totals ---------- */

.fg-pdf-bottom-table {
	margin-bottom: 12px;
}

.fg-pdf-bottom-left-cell {
	width: 55%;
	vertical-align: top;
	padding-right: 10px;
}

.fg-pdf-bottom-right-cell {
	width: 45%;
	vertical-align: top;
}

.fg-pdf-validity-box {
	background: #eaf4fb;
	border-radius: 6px;
	padding: 8px 10px;
}

.fg-pdf-icon-lg {
	width: 26px;
	height: 26px;
	color: #2f7fc2;
	float: left;
	margin-right: 8px;
}

.fg-pdf-validity-text {
	font-size: 8pt;
	overflow: hidden;
}

.fg-pdf-price-scheme {
	margin-top: 3px;
	color: #2f7fc2;
	font-weight: bold;
}

.fg-pdf-totals {
	background: #f5f9fc;
	border-radius: 6px;
	overflow: hidden;
}

.fg-pdf-totals td {
	padding: 5px 8px;
	font-size: 8.5pt;
}

.fg-pdf-totals-icon {
	width: 22px;
	color: #2f7fc2;
}

.fg-pdf-icon-sm {
	width: 12px;
	height: 12px;
	vertical-align: middle;
	color: #ffffff;
}

.fg-pdf-totals-icon .fg-pdf-icon-sm {
	color: #2f7fc2;
}

.fg-pdf-totals-label {
	text-align: left;
}

.fg-pdf-totals-value {
	text-align: right;
	font-weight: bold;
}

.fg-pdf-totals-grand {
	background: #0d3b66;
}

.fg-pdf-totals-grand td {
	color: #ffffff;
	font-weight: bold;
	font-size: 10pt;
	padding: 7px 8px;
}

/* ---------- Signature ---------- */

.fg-pdf-signature {
	margin-bottom: 14px;
}

.fg-pdf-signature-name {
	font-size: 13pt;
	font-style: italic;
	color: #0d3b66;
}

.fg-pdf-signature-line {
	border-top: 1px solid #8496a6;
	width: 200px;
	margin-top: 4px;
}

.fg-pdf-signature-title {
	font-size: 8pt;
	color: #5c7791;
	margin-top: 2px;
}

/* ---------- Decorative line ---------- */

.fg-pdf-decor {
	text-align: right;
	color: #a9c7de;
	font-style: italic;
	font-size: 9pt;
	margin-bottom: 8px;
}

/* ---------- Footer ---------- */

.fg-pdf-footer-table {
	background: #0d3b66;
	border-radius: 6px;
}

.fg-pdf-footer-cell {
	color: #ffffff;
	font-size: 8pt;
	padding: 8px 10px;
	text-align: center;
	width: 33.33%;
}

.fg-pdf-icon-sm-white {
	width: 11px;
	height: 11px;
	vertical-align: middle;
	margin-right: 4px;
	color: #ffffff;
}

/* Commit 25.23 -- "Fabrigray Factura Comercial" Print Format (Pick List).
   Same rules as "Fabrigray Cotización Comercial": table-based layout only
   (no grid/flexbox/position:fixed/vh/vw/JS) for wkhtmltopdf, and every
   selector scoped under .fg-inv so nothing leaks into another format.
   Sober A4 layout: logo | issuer | FACTURA DE VENTA box, customer block,
   items, total in words + TOTAL, notes, two signatures, small footer. */

.fg-inv {
	font-family: "Helvetica Neue", Arial, sans-serif;
	color: #1f2933;
	font-size: 9pt;
	line-height: 1.3;
}

.fg-inv table {
	width: 100%;
	border-collapse: collapse;
}

/* ---------- Draft banner ---------- */

.fg-inv-draft {
	border: 1.5px solid #b42318;
	color: #b42318;
	text-align: center;
	padding: 5px 8px;
	margin-bottom: 8px;
	font-size: 8pt;
}

.fg-inv-draft strong {
	font-size: 9.5pt;
	letter-spacing: 0.5px;
}

/* ---------- Header ---------- */

.fg-inv-header {
	margin-bottom: 8px;
}

.fg-inv-header td {
	vertical-align: top;
}

.fg-inv-logo-cell {
	width: 120px;
	vertical-align: middle !important;
}

.fg-inv-logo {
	max-width: 110px;
	max-height: 80px;
}

/* No logo yet: a controlled placeholder (issuer name in a dashed box),
   never an invented image. Long names wrap inside the box. */
.fg-inv-logo-placeholder {
	width: 100px;
	padding: 14px 4px;
	border: 1px dashed #9aa5b1;
	color: #52606d;
	font-weight: bold;
	font-size: 8pt;
	line-height: 1.2;
	text-align: center;
	word-wrap: break-word;
}

.fg-inv-issuer-cell {
	text-align: center;
	padding: 0 10px;
}

.fg-inv-issuer-name {
	font-size: 15pt;
	font-weight: bold;
	color: #102a43;
	letter-spacing: 0.3px;
	margin-bottom: 1px;
}

.fg-inv-issuer-nit {
	font-size: 9pt;
	font-weight: bold;
	margin-bottom: 1px;
}

.fg-inv-issuer-line {
	font-size: 8pt;
	line-height: 1.25;
}

.fg-inv-box-cell {
	width: 210px;
}

.fg-inv-box {
	border: 1.2px solid #102a43;
}

.fg-inv-box td {
	padding: 3px 6px;
	font-size: 8pt;
	border-top: 1px solid #bcccdc;
}

.fg-inv-box-title {
	background: #102a43;
	color: #ffffff;
	text-align: center;
	font-weight: bold;
	font-size: 10.5pt !important;
	letter-spacing: 1px;
	border-top: none !important;
}

.fg-inv-box-number {
	text-align: center;
	font-weight: bold;
	font-size: 11pt !important;
	color: #b42318;
}

.fg-inv-box-label {
	font-weight: bold;
	color: #486581;
	width: 50%;
}

.fg-inv-box-value {
	text-align: right;
}

.fg-inv-ref {
	margin-top: 3px;
	font-size: 7pt;
	color: #7b8794;
	text-align: right;
}

/* ---------- Customer ---------- */

.fg-inv-customer {
	border: 1px solid #9aa5b1;
	margin-bottom: 8px;
}

.fg-inv-customer td {
	padding: 3px 6px;
	font-size: 8.5pt;
	vertical-align: top;
}

.fg-inv-customer-label {
	width: 70px;
	font-weight: bold;
	color: #486581;
	white-space: nowrap;
}

/* ---------- Items ---------- */

.fg-inv-items {
	border: 1px solid #9aa5b1;
	margin-bottom: 0;
}

.fg-inv-items thead {
	display: table-header-group;
}

.fg-inv-items tbody tr {
	page-break-inside: avoid;
}

.fg-inv-items th {
	background: #d9e2ec;
	color: #102a43;
	font-size: 8pt;
	font-weight: bold;
	padding: 4px 6px;
	border-bottom: 1px solid #9aa5b1;
}

.fg-inv-items td {
	padding: 3px 6px;
	font-size: 8.5pt;
	border-left: 1px solid #d9e2ec;
	vertical-align: top;
}

.fg-inv-items td:first-child {
	border-left: none;
}

.fg-inv-col-qty {
	width: 55px;
	text-align: center;
}

.fg-inv-col-desc {
	text-align: left;
}

.fg-inv-col-num {
	width: 105px;
	text-align: right;
}

/* ---------- Totals ---------- */

.fg-inv-totals {
	border: 1px solid #9aa5b1;
	border-top: none;
	margin-bottom: 8px;
}

.fg-inv-words-cell {
	padding: 6px;
	font-size: 8.5pt;
	vertical-align: middle;
}

.fg-inv-words-label {
	font-weight: bold;
	color: #486581;
	margin-right: 4px;
}

.fg-inv-totals-cell {
	width: 230px;
	border-left: 1px solid #9aa5b1;
	vertical-align: bottom;
}

.fg-inv-totals-table td {
	padding: 3px 6px;
	font-size: 8.5pt;
}

.fg-inv-totals-label {
	text-align: left;
}

.fg-inv-totals-value {
	text-align: right;
	font-weight: bold;
}

.fg-inv-totals-grand td {
	background: #102a43;
	color: #ffffff;
	font-size: 11pt;
	padding: 5px 6px;
}

/* ---------- Notes + people ---------- */

.fg-inv-notes {
	margin-bottom: 26px;
	page-break-inside: avoid;
}

.fg-inv-notes-cell {
	border: 1px solid #9aa5b1;
	padding: 4px 6px;
	vertical-align: top;
}

.fg-inv-notes-label,
.fg-inv-people-label {
	font-weight: bold;
	color: #486581;
	font-size: 8pt;
}

.fg-inv-notes-text {
	font-size: 8.5pt;
	line-height: 1.35;
	white-space: pre-wrap;
	word-wrap: break-word;
	overflow-wrap: break-word;
}

.fg-inv-notes-empty {
	padding: 0;
}

.fg-inv-people-cell {
	width: 260px;
	padding: 4px 0 4px 12px;
	vertical-align: top;
	font-size: 8.5pt;
}

.fg-inv-people-cell div {
	margin-bottom: 6px;
}

/* ---------- Signatures ---------- */

.fg-inv-signatures {
	margin-bottom: 10px;
	page-break-inside: avoid;
}

.fg-inv-signature-cell {
	width: 42%;
	text-align: center;
	vertical-align: bottom;
}

.fg-inv-signature-gap {
	width: 16%;
}

.fg-inv-signature-line {
	border-top: 1px solid #1f2933;
	margin-top: 30px;
}

.fg-inv-signature-title {
	font-weight: bold;
	font-size: 8.5pt;
	margin-top: 2px;
}

.fg-inv-signature-sub {
	font-size: 7.5pt;
	color: #52606d;
}

/* ---------- Legal footer ----------
   Long legal text: its own clearly separated block after the signatures,
   small but readable, never truncated (no overflow/height limits) -- it
   simply flows onto the next page if a long invoice needs it. The payment
   instruction is set apart from the legal paragraph. */

.fg-inv-legal {
	border-top: 1.2px solid #102a43;
	padding-top: 5px;
	page-break-inside: avoid;
}

.fg-inv-legal p {
	margin: 0;
}

.fg-inv-legal-text {
	font-size: 6.8pt;
	line-height: 1.35;
	color: #3e4c59;
	text-align: justify;
}

.fg-inv-legal-payment {
	margin-top: 5px !important;
	padding: 4px 6px;
	border: 1px solid #9aa5b1;
	background: #f0f4f8;
	font-size: 7.5pt;
	font-weight: bold;
	color: #102a43;
	text-align: center;
}

/* ---------- Print provider (imprenta) ----------
   Last line of the invoice, shared by every issuer: small and discreet
   but readable, separated by a thin rule. */

.fg-inv-printer {
	margin-top: 6px;
	padding-top: 3px;
	border-top: 1px solid #bcccdc;
	font-size: 6.5pt;
	color: #52606d;
	text-align: center;
}
